messages.content:
Great choice. Here’s a self-contained, runnable Node.js + Express example using PostgreSQL (pg) with plain JavaScript. It demonstrates:
- Parameterized queries to prevent SQL injection
- HTML escaping for safe rendering
- A minimal Express app with a simple endpoint to submit and render user content
- Basic CSP header to add protection

Prerequisites:
- Node.js and npm installed
- PostgreSQL database running
- Create a database (e.g., testdb) and a user with appropriate privileges
- Install dependencies: npm install express pg he

Project structure (suggested):
- app.js
- views/index.html (or use a simple template string for rendering)
- package.json

Code (app.js):
const express = require('express');
const { Pool } = require('pg');
const escapeHtml = (str) => {
  if (typeof str !== 'string') return '';
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

const app = express();
const port = process.env.PORT || 3000;

// PostgreSQL connection pool
const pool = new Pool({
  user: 'your_db_user',
  host: 'localhost',
  database: 'testdb',
  password: 'your_db_password',
  port: 5432,
});

// Middleware
app.use(express.json());

// Simple in-memory template for demonstration (adjust to your templating choice)
function renderPage({ username, comment }) {
  // Escape before rendering
  const safeUsername = escapeHtml(username);
  const safeComment = escapeHtml(comment);

  // Very basic HTML page with a minimal CSP
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Safe Rendering Demo</title>
  <meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'">
</head>
<body>
  <h1>Safe Rendering Demo</h1>
  <form id="submitForm" method="post" action="/submit">
    <label>Username: <input name="username" /></label><br/>
    <label>Comment: <textarea name="comment"></textarea></label><br/>
    <button type="submit">Submit</button>
  </form>

  <h2>Stored Content</h2>
  <p><strong>User:</strong> ${safeUsername}</p>
  <p><strong>Comment:</strong> ${safeComment}</p>
</body>
</html>`;
}

// Route to display the page and current content
app.get('/', async (req, res) => {
  // Fetch last 5 comments for display (safe rendering via escaping)
  try {
    const { rows } = await pool.query('SELECT username, comment FROM comments ORDER BY id DESC LIMIT 5');
    // Render a simple page including the last entry in a sanitized way
    const last = rows[0] || { username: '', comment: '' };
    const html = renderPage({ username: last.username, comment: last.comment });
    res.send(html);
  } catch (err) {
    console.error('DB error:', err);
    res.status(500).send('Database error');
  }
});

// Route to handle form submission (sanitized and stored safely)
app.post('/submit', async (req, res) => {
  // Expecting JSON or URL-encoded body; enable parsing accordingly
  const { username, comment } = req.body;

  // In case content is coming as JSON with properties
  const u = (username != null) ? String(username) : '';
  const c = (comment != null) ? String(comment) : '';

  // Escape for HTML rendering, but store original (escaped) content to minimize risk
  // Best practice: store either sanitized text or store raw and escape on render.
  const safeUsername = escapeHtml(u);
  const safeComment = escapeHtml(c);

  // Use parameterized query to insert data; store the escaped values to reduce risk
  try {
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      const insertQuery = 'INSERT INTO comments (username, comment) VALUES ($1, $2) RETURNING id';
      const result = await client.query(insertQuery, [safeUsername, safeComment]);
      await client.query('COMMIT');
      // Redirect to home to show updated content
      res.redirect('/');
    } catch (err) {
      await client.query('ROLLBACK');
      console.error('Insert error:', err);
      res.status(500).send('Insert failed');
    } finally {
      client.release();
    }
  } catch (err) {
    console.error('Connection error:', err);
    res.status(500).send('Database connection error');
  }
});

// Ensure the table exists (simple setup)
async function ensureTable() {
  const createSql = `
    CREATE TABLE IF NOT EXISTS comments (
      id SERIAL PRIMARY KEY,
      username TEXT NOT NULL,
      comment TEXT NOT NULL,
      created_at TIMESTAMP DEFAULT NOW()
    )
  `;
  try {
    await pool.query(createSql);
    console.log('Table ensured');
  } catch (err) {
    console.error('Error ensuring table:', err);
  }
}

app.listen(port, async () => {
  console.log(`Server running at http://localhost:${port}`);
  await ensureTable();
});

Notes and best practices:
- SQL injection prevention: All DB interactions use parameterized queries ($1, $2, …) via pg.
- HTML escaping: User-provided data is escaped before rendering. If you want to render user content as-is in a template, consider using a templating engine that auto-escapes by default (e.g., EJS by default escapes variables with <%= … %> vs <%- … %> to output raw HTML). Here, we explicitly escape with a helper.
- Content Security Policy (CSP): A minimal CSP is included to reduce risk of inline scripts. You can extend this to fit your app.
- Data flow choice: This example escapes before storing. Some teams prefer storing raw user input and escaping only at render; pick a policy and stay consistent.
- Error handling: Basic error handling is included. In production, consider more robust logging and user-safe error messages.

What to customize:
- Replace database credentials (user, password) with your actual values.
- If you want to render with a template engine (EJS, Pug, etc.), wire it up and ensure escaping is enabled by default.
- If you prefer JSON-based API endpoints, you can adapt the /submit route to accept JSON and respond with JSON rather than redirecting.

Would you like me to tailor this further to use EJS templates and include a separate view file, or adapt for a specific PostgreSQL client setup (e.g., pooling options, SSL) or TypeScript support?

