          "key": "Content-Security-Policy",
          "value": "default-src 'self'; img-src 'self' https://cdn.example.com; script-src 'self' 'nonce-__NONCE__'; style-src 'self' 'unsafe-inline'; object-src 'none'"
        },
        {
          "key": "X-Content-Type-Options",
