Create folder vercel/api and add nonce.ts (TypeScript)

import { VercelRequest, VercelResponse } from '@vercel/node';
import crypto from 'crypto';

export default function handler(req: VercelRequest, res: VercelResponse) {
  // Generate a random nonce
  const nonce = crypto.randomBytes(16).toString('base64');

  // In a real app, you’d render a shell HTML that includes a script tag with nonce
  // For demonstration, we return the nonce in JSON and also a minimal HTML shell
  res.setHeader('Content-Type', 'application/json');
  res.status(200).json({ nonce });
}

3) serverless shell utility: vercel/api/nonce-shell.ts
This could serve a minimal HTML shell that includes the nonce in a script tag and bootstraps the SPA.
Note: In a full setup you’d fetch nonce from /api/nonce and inject into HTML. Here we provide a simple static shell example and a minimal fetch integration that your client can use.

import { VercelRequest, VercelResponse } from '@vercel/node';
import fs from 'fs';
import path from 'path';

export default async function handler(req: VercelRequest, res: VercelResponse) {
  // In a real scenario, fetch the nonce from a secure store or call /api/nonce
  // For demonstration, we embed a placeholder. The client app can replace it via fetch.
  const nonce = 'REPLACE_WITH_REAL_NONCE';

  const htmlPath = path.join(process.cwd(), 'public', 'index.html');
  let indexHtml = fs.readFileSync(htmlPath, 'utf8');

  // Inject placeholder nonce into a script tag if present
  indexHtml = indexHtml.replace("__NONCE__", nonce);

  res.setHeader('Content-Type', 'text/html');
  res.status(200).send(indexHtml);
}

