src/App.tsx

import React, { useEffect, useState } from 'react';
import SafeText from './components/SafeText';
import SafeHtml from './components/SafeHtml';
import UserButton from './components/UserButton';

function App() {
  const dangerous = "<script>alert('xss')</script>";
  const safeSnippet = "<strong>Safe content</strong>";

  const [nonce, setNonce] = useState<string | null>(null);

  useEffect(() => {
    // Demonstration: fetch a nonce from the nonce API (in real deployment this would be wired to the shell)
    fetch('/api/nonce')
      .then((r) => r.json())
      .then((data) => {
        if (data?.nonce) setNonce(data.nonce);
      })
      .catch(() => {
        // Fallback for demonstration
        setNonce(null);
      });
  }, []);

  return (
    <div style={{ padding: 20 }}>
      <h1>CRA on Vercel: Safe Rendering Demo (Nonce Demo)</h1>

      <section>
        <h2>Plain text (safe by React)</h2>
        <SafeText text={dangerous} />
      </section>

      <section>
        <h2>Sanitized HTML (DOMPurify)</h2>
        <SafeHtml html={dangerous + safeSnippet} />
      </section>

      <section>
        <h2>Inline script demo (with nonce)</h2>
        {nonce ? (
          <div>
            <p>Nonce available: {nonce}</p>
            <div
              dangerouslySetInnerHTML={{
                __html: "<script nonce='" + nonce + "'>console.log('nonce-script executed');</script>"
              }}
            />
          </div>
        ) : (
          <p>Loading nonce...</p>
        )}
      </section>

      <section>
        <h2>External interaction</h2>
        <UserButton onClickMessage="Hello from user data" />
      </section>
    </div>
  );
}

export default App;

