  // Set CSP header to include nonce for inline scripts
  res.setHeader('Content-Type', 'text/html');
  res.setHeader(
    'Content-Security-Policy',
    `default-src 'self'; img-src 'self' https://cdn.example.com; script-src 'self' 'nonce-${nonce}'; style-src 'self' 'unsafe-inline'; object-src 'none'`
  );

