import { NowRequest, NowResponse } from '@vercel/node';
import crypto from 'crypto';
import path from 'path';
import fs from 'fs';

export default async function handler(req: NowRequest, res: NowResponse) {
  const nonce = crypto.randomBytes(16).toString('base64');

  // Load and rewrite the HTML shell with the real nonce
  const templatePath = path.join(process.cwd(), 'public', 'index.html.template');
  let html = fs.existsSync(templatePath)
    ? fs.readFileSync(templatePath, 'utf8')
    : '<html></html>';

  html = html.replace('__NONCE__', nonce);

  // Set CSP header including nonce
  res.setHeader('Content-Type', 'text/html');
  res.setHeader(
    'Content-Security-Policy',
    `default-src 'self'; img-src 'self' https://cdn.example.com; script-src 'self' 'nonce-${nonce}'; style-src 'self' 'unsafe-inline'; object-src 'none'`
  );

  res.status(200).send(html);
}

